      analysis: [],
      annotations: this.loadTable("annotations"),
      labels: this.loadTable("labels"),
      comments: this.loadTable("comments"),
      regions: this.loadTable("regions"),
      evidence: this.loadTable("evidence"),
      imports: this.loadTable("imports"),
      runtime: []
